/**
 * @param {number[]} xs - values to average
 * @returns {number} the mean, or 0 for an empty array
 */
function mean(xs) {
  if (xs.length === 0) return 0;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

console.log(mean([2, 4, 6]));
console.log(mean([]));

