function parseAge(raw) {
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 0) {
    throw new Error("age must be a non-negative integer, got: " + raw);
  }
  return n;
}

console.log(parseAge("42"));
try {
  parseAge("abc");
} catch (e) {
  console.log(e.message);
}

