function groupBy(xs, keyFn) {
  const out = {};
  for (const x of xs) {
    const k = keyFn(x);
    (out[k] = out[k] || []).push(x);
  }
  return out;
}

console.log(groupBy([1, 2, 3, 4], n => (n % 2 === 0 ? "even" : "odd")));
console.log(groupBy(["aa", "b"], s => s.length));

