function uniqueBy(xs, keyFn) {
  const seen = new Set();
  const out = [];
  for (const x of xs) {
    const k = keyFn(x);
    if (!seen.has(k)) {
      seen.add(k);
      out.push(x);
    }
  }
  return out;
}

