function clampToRange(value, min, max) {
  if (min > max) {
    throw new Error("invalid range: min above max");
  }
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

function toNumberList(values) {
  const out = [];
  for (const v of values) {
    if (v === null || v === undefined || v === "") continue;
    const n = Number(v);
    if (Number.isFinite(n)) out.push(n);
  }
  return out;
}

function partition(xs, predicate) {
  const yes = [];
  const no = [];
  for (const x of xs) {
    if (predicate(x)) yes.push(x);
    else no.push(x);
  }
  return [yes, no];
}

function safeGet(obj, path, fallback) {
  let cur = obj;
  for (const key of path) {
    if (cur === null || cur === undefined || !(key in Object(cur))) {
      return fallback;
    }
    cur = cur[key];
  }
  return cur;
}

